  {
    if (Instance == 2U)
    {
      for (i = 0; i < DFSDM_MIC_NUMBER; i ++)
      {
        if (((Device >> i) & AUDIO_IN_DEVICE_DIGITAL_MIC1) == AUDIO_IN_DEVICE_DIGITAL_MIC1)
        {
          if (HAL_DFSDM_ChannelDeInit(&haudio_in_dfsdm_channel[i]) != HAL_OK)
